/* Allow importing CSS files as side-effect modules */
declare module '*.css';

/* Allow importing image files as data-URI strings */
declare module '*.png' {
  const src: string;
  export default src;
}

declare module '*.jpg' {
  const src: string;
  export default src;
}

declare module '*.gif' {
  const src: string;
  export default src;
}

declare module '*.svg' {
  const src: string;
  export default src;
}
